def openings(y) { (y > 1.5) * (y < 2.5) + (y > -2.5) * (y < -1.5) }
def slit(x, y) { 60 * (x > 0) * (x < 0.4) * (1 - openings(y)) }
qm2 grid -6 6 30, -6 6 30
qm2 potential slit

def g2(x, y) { x }
def f2(t) { 0.3 * cos(t) }
qm2 grid -4 4 20, -4 4 20
qm2 potential zero
qm2 packet 0 0, 1 1, 1 0
qm2 drive g2 f2

def g3(x, y, z) { x }
def f3(t) { 0.3 * cos(t) }
qm3 grid -3 3 10, -3 3 10, -3 3 10
qm3 potential zero
qm3 packet 0 0 0, 1 1 1, 1 0 0
qm3 drive g3 f3
